import {takeInheritanceMarkup,takePresetDisplay,takeInheritanceChange,lockInheritedTakeControls} from './take-preset-inheritance-editor.js';
import {resolveTakeSettings} from './take-settings.js';
import {validTakePreset} from './take-preset-assets.js';
import {takeSettingsMarkup,takeSettingsInput} from './take-settings-editor.js';
import {takeSourceInput,takeSourceAction} from './take-sources.js';
import {takeSourcesMarkup} from './take-sources-editor.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderTakePresetEditor(element,doc,hooks,files=[]){
 const refresh=()=>renderTakePresetEditor(element,doc,hooks,files),display=takePresetDisplay(element,doc,hooks,refresh),d=display.data,settings=resolveTakeSettings(d.settings);element.dataset.takePresetEditor='';element.dataset.takePresetPath=doc.path;element.innerHTML='<header class="asset-editor-heading"><div><small>Take 녹화 프리셋</small><h2>'+esc(d.name)+'</h2></div></header><div class="asset-form">'+takeInheritanceMarkup(doc,files,display)+'<section><label>이름<input data-take-asset="name" value="'+esc(d.name)+'" maxlength="80"></label><label>FPS<input data-take-asset="fps" type="number" min="1" max="240" step="1" value="'+d.fps+'"></label><label>키 오차<input data-take-asset="tolerance" type="number" min="0" step="any" value="'+d.tolerance+'"></label><label>설명<textarea data-take-asset="description" maxlength="1000">'+esc(d.description||'')+'</textarea></label></section><section>'+takeSourcesMarkup(d.sources,hooks.world?.().objects,!!hooks.running?.())+takeSettingsMarkup(settings,false)+'</section></div>';
 lockInheritedTakeControls(element,doc.data);
 element.onclick=event=>{const control=event.target.closest('[data-take-inherit-refresh],[data-take-inherit-detach]');if(control){if(control.hasAttribute('data-take-inherit-refresh')){delete element.hbTakePresetResolved;refresh();return;}try{if(hooks.running?.())throw Error('실행을 종료한 뒤 편집하세요.');if(!display.ready)throw Error('상위 설정을 먼저 읽으세요.');const next=structuredClone(display.data);hooks.before();doc.data=next;hooks.change();refresh();}catch(error){hooks.error(error.message);}return;}const button=event.target.closest('[data-take-source-add],[data-take-source-selection],[data-take-source-remove]');if(!button)return;try{if(hooks.running?.())throw Error('실행을 종료한 뒤 소스를 편집하세요.');const next=structuredClone(doc.data);next.sources=takeSourceAction(button,next.sources,element,hooks.world?.());if(!validTakePreset(next))throw Error('녹화 소스를 확인하세요.');hooks.before();doc.data=next;hooks.change();refresh();}catch(error){hooks.error(error.message);refresh();}};
 element.onchange=event=>{const input=event.target,next=structuredClone(doc.data);try{if(hooks.running?.())throw Error('실행을 종료한 뒤 프리셋을 편집하세요.');if(takeInheritanceChange(input,next,display)){}else if(input.hasAttribute('data-take-source-mode')){if(input.value==='selection')delete next.sources;else next.sources=[];}else if(input.dataset.takeSourceField){next.sources=takeSourceInput(input,next.sources||[]);}else if(input.dataset.takeAsset){const key=input.dataset.takeAsset;next[key]=['fps','tolerance'].includes(key)?Number(input.value):input.value;}else{const current=resolveTakeSettings(next.settings),settings=takeSettingsInput(input,current,current.spawnFilter.plane);if(!settings)return;next.settings=settings;}if(!validTakePreset(next))throw Error('프리셋 이름·FPS·키 오차·녹화 설정을 확인하세요.');hooks.before();doc.data=next;hooks.change();refresh();}catch(error){hooks.error(error.message);refresh();}};
}
